        {
            "op": "cd",

elif op[0] == "cb":
    # 配置回滚：按目标快照执行 ci 的原子替换与默认运行态重建，成功
    # 另建新 rev；全部校验先于任何变更，失败天然回滚时钟、配置、
    # 运行态、rev 与历史。
    _, target_rev, now = op
    snapshot = None
    for rev, committed in commit_history:
        if rev == target_rev:
            snapshot = committed
            break
